ALTER TABLE public.reportes ADD COLUMN IF NOT EXISTS ocorrido_em timestamptz, ADD COLUMN IF NOT EXISTS detetado_em timestamptz, ADD COLUMN IF NOT EXISTS causa_alegada text, ADD COLUMN IF NOT EXISTS referencia_tipo text, ADD COLUMN IF NOT EXISTS referencia_externa text, ADD COLUMN IF NOT EXISTS up_care_referencia text, ADD COLUMN IF NOT EXISTS tipo_causa text NOT NULL DEFAULT 'desconhecida', ADD COLUMN IF NOT EXISTS conclusao text, ADD COLUMN IF NOT EXISTS evidencia_apuracao text, ADD COLUMN IF NOT EXISTS apurado_por uuid REFERENCES public.funcionarios(id), ADD COLUMN IF NOT EXISTS apurado_em timestamptz, ADD COLUMN IF NOT EXISTS erro_confirmado boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS responsaveis_apurados uuid[] NOT NULL DEFAULT '{}', ADD COLUMN IF NOT EXISTS corrigido_por uuid REFERENCES public.funcionarios(id), ADD COLUMN IF NOT EXISTS validado_por uuid REFERENCES public.funcionarios(id), ADD COLUMN IF NOT EXISTS correcao_resultado text, ADD COLUMN IF NOT EXISTS validacao_evidencia text;
CREATE TABLE public.reporte_envolvidos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporte_id uuid NOT NULL REFERENCES public.reportes(id),funcionario_id uuid NOT NULL REFERENCES public.funcionarios(id),ativo boolean NOT NULL DEFAULT true,marcado_por uuid NOT NULL REFERENCES public.funcionarios(id),marcado_em timestamptz NOT NULL DEFAULT now(),UNIQUE(reporte_id,funcionario_id));
GRANT SELECT ON public.reporte_envolvidos TO authenticated; GRANT ALL ON public.reporte_envolvidos TO service_role; ALTER TABLE public.reporte_envolvidos ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.reporte_respostas_individuais(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),envolvido_id uuid NOT NULL REFERENCES public.reporte_envolvidos(id),autor_id uuid NOT NULL REFERENCES public.funcionarios(id),resposta text NOT NULL CHECK(resposta IN ('reconheco','contesto','esclarecimentos')),texto text NOT NULL CHECK(length(trim(texto)) BETWEEN 15 AND 10000),criado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.reporte_respostas_individuais TO authenticated; GRANT ALL ON public.reporte_respostas_individuais TO service_role; ALTER TABLE public.reporte_respostas_individuais ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.reporte_notificacoes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporte_id uuid NOT NULL REFERENCES public.reportes(id),destinatario_id uuid NOT NULL REFERENCES public.funcionarios(id),mensagem text NOT NULL,lida_em timestamptz,criado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.reporte_notificacoes TO authenticated; GRANT ALL ON public.reporte_notificacoes TO service_role; ALTER TABLE public.reporte_notificacoes ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.reporte_ficheiros(id uuid PRIMARY KEY,reporte_id uuid REFERENCES public.reportes(id),evento_id uuid REFERENCES public.reporte_eventos(id),resposta_id uuid REFERENCES public.reporte_respostas_individuais(id),uploader_id uuid NOT NULL REFERENCES public.funcionarios(id),caminho text NOT NULL UNIQUE,nome text NOT NULL,mime text NOT NULL,tamanho bigint NOT NULL CHECK(tamanho BETWEEN 1 AND 20971520),fase text NOT NULL CHECK(fase IN ('abertura','resposta','comentario','correcao','validacao','apuracao','atribuicao')),estado text NOT NULL DEFAULT 'pendente' CHECK(estado IN ('pendente','ligado','falhou')),criado_em timestamptz NOT NULL DEFAULT now(),ligado_em timestamptz);
GRANT SELECT ON public.reporte_ficheiros TO authenticated; GRANT ALL ON public.reporte_ficheiros TO service_role; ALTER TABLE public.reporte_ficheiros ENABLE ROW LEVEL SECURITY;
CREATE INDEX ON public.reporte_envolvidos(funcionario_id,reporte_id) WHERE ativo; CREATE INDEX ON public.reporte_notificacoes(destinatario_id,lida_em); CREATE INDEX ON public.reporte_ficheiros(reporte_id); CREATE INDEX ON public.reporte_respostas_individuais(envolvido_id);
CREATE OR REPLACE FUNCTION public.central_gestor() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND public.has_role(auth.uid(),'gestor'::public.app_role) AND EXISTS(SELECT 1 FROM public.funcionarios WHERE user_id=auth.uid() AND ativo); $$;
CREATE OR REPLACE FUNCTION public.central_ver(p_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.reportes r WHERE r.id=p_id AND (public.central_gestor() OR r.reportado_por=public.rc_meu_funcionario_id() OR r.assumido_por=public.rc_meu_funcionario_id() OR public.rc_pertence_setor(r.setor_destino_id) OR public.rc_pertence_setor(r.setor_origem_id) OR EXISTS(SELECT 1 FROM public.reporte_envolvidos e WHERE e.reporte_id=r.id AND e.funcionario_id=public.rc_meu_funcionario_id() AND e.ativo))); $$;
CREATE OR REPLACE FUNCTION public.central_gerir(p_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.central_gestor() OR EXISTS(SELECT 1 FROM public.reportes r WHERE r.id=p_id AND public.rc_e_responsavel(r.setor_destino_id)); $$;
CREATE POLICY central_envolvidos_read ON public.reporte_envolvidos FOR SELECT TO authenticated USING(public.central_ver(reporte_id)); CREATE POLICY central_respostas_read ON public.reporte_respostas_individuais FOR SELECT TO authenticated USING(autor_id=public.rc_meu_funcionario_id() OR public.central_gestor()); CREATE POLICY central_notificacoes_read ON public.reporte_notificacoes FOR SELECT TO authenticated USING(destinatario_id=public.rc_meu_funcionario_id()); CREATE POLICY central_ficheiros_read ON public.reporte_ficheiros FOR SELECT TO authenticated USING(estado='ligado' AND public.central_ver(reporte_id) AND (resposta_id IS NULL OR public.central_gestor() OR uploader_id=public.rc_meu_funcionario_id()));
DROP POLICY IF EXISTS rc_sel_reportes ON public.reportes; CREATE POLICY rc_sel_reportes ON public.reportes FOR SELECT TO authenticated USING(public.central_ver(id)); DROP POLICY IF EXISTS rc_upd_reportes ON public.reportes; REVOKE UPDATE ON public.reportes FROM authenticated;
DROP POLICY IF EXISTS rc_sel_eventos ON public.reporte_eventos; CREATE POLICY rc_sel_eventos ON public.reporte_eventos FOR SELECT TO authenticated USING(public.central_ver(reporte_id)); DROP POLICY IF EXISTS rc_ins_eventos ON public.reporte_eventos; CREATE POLICY rc_ins_eventos ON public.reporte_eventos FOR INSERT TO authenticated WITH CHECK(autor_id=public.rc_meu_funcionario_id() AND tipo='comentario' AND public.central_ver(reporte_id) AND length(trim(texto)) BETWEEN 3 AND 10000 AND cardinality(anexos)=0);
CREATE OR REPLACE FUNCTION public.central_append_only() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Histórico imutável: acrescenta um novo registo.'; END $$;
CREATE TRIGGER central_eventos_imutaveis BEFORE UPDATE OR DELETE ON public.reporte_eventos FOR EACH ROW EXECUTE FUNCTION public.central_append_only(); CREATE TRIGGER central_respostas_imutaveis BEFORE UPDATE OR DELETE ON public.reporte_respostas_individuais FOR EACH ROW EXECUTE FUNCTION public.central_append_only();
CREATE OR REPLACE FUNCTION public.rc_fn_log_estado() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF new.estado IS DISTINCT FROM old.estado THEN INSERT INTO public.reporte_eventos(reporte_id,autor_id,tipo,estado_anterior,estado_novo,texto) VALUES(new.id,coalesce(public.rc_meu_funcionario_id(),old.reportado_por),'mudanca_estado',old.estado,new.estado,nullif(current_setting('app.central_texto',true),'')); new.fechado_em:=CASE WHEN new.estado IN ('validado','nao_procede') THEN now() END; END IF; new.atualizado_em:=now(); RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.rc_mudar_estado(p_reporte uuid,p_novo_estado text,p_texto text,p_data_prevista date DEFAULT NULL) RETURNS public.reportes LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.reportes; eu uuid:=public.rc_meu_funcionario_id(); res public.reportes; BEGIN SELECT * INTO r FROM public.reportes WHERE id=p_reporte FOR UPDATE; IF NOT FOUND OR eu IS NULL OR NOT public.central_ver(p_reporte) THEN RAISE EXCEPTION 'Sem acesso ao reporte.'; END IF; IF length(trim(coalesce(p_texto,''))) NOT BETWEEN 15 AND 10000 THEN RAISE EXCEPTION 'Descreve a ação entre 15 e 10000 caracteres.'; END IF; CASE WHEN p_novo_estado='a_tratar' AND r.estado='pendente' THEN IF NOT public.central_gerir(p_reporte) THEN RAISE EXCEPTION 'Só o responsável do setor ou gestor pode atribuir.'; END IF; IF p_data_prevista IS NULL THEN RAISE EXCEPTION 'Indica a data prevista.'; END IF; WHEN p_novo_estado='corrigido' AND r.estado='a_tratar' THEN IF NOT (public.central_gerir(p_reporte) OR r.assumido_por=eu) THEN RAISE EXCEPTION 'Só quem executa a correção ou gestor pode corrigir.'; END IF; WHEN p_novo_estado='nao_procede' AND r.estado IN ('pendente','a_tratar') THEN IF NOT public.central_gerir(p_reporte) THEN RAISE EXCEPTION 'Sem permissão para arquivar.'; END IF; WHEN p_novo_estado='validado' AND r.estado='corrigido' THEN IF NOT public.central_gestor() THEN RAISE EXCEPTION 'Só um gestor pode validar.'; END IF; IF r.corrigido_por IS NULL OR length(trim(coalesce(r.correcao_resultado,'')))<15 THEN RAISE EXCEPTION 'Falta evidência da correção.'; END IF; IF r.corrigido_por=eu THEN RAISE EXCEPTION 'A validação exige outro gestor, diferente de quem corrigiu.'; END IF; WHEN p_novo_estado='a_tratar' AND r.estado IN ('corrigido','nao_procede') THEN IF NOT(public.central_gestor() OR r.reportado_por=eu) THEN RAISE EXCEPTION 'Só o gestor ou autor pode rejeitar com motivo.'; END IF; ELSE RAISE EXCEPTION 'Transição inválida.'; END CASE; PERFORM set_config('app.rc_transicao','1',true); PERFORM set_config('app.central_texto',trim(p_texto),true); UPDATE public.reportes SET estado=p_novo_estado,assumido_por=CASE WHEN r.estado='pendente' AND p_novo_estado='a_tratar' THEN coalesce(assumido_por,eu) ELSE assumido_por END,data_prevista=coalesce(p_data_prevista,data_prevista),respondido_em=CASE WHEN p_novo_estado='a_tratar' THEN coalesce(respondido_em,now()) ELSE respondido_em END,prazo_resolucao=CASE WHEN p_novo_estado='a_tratar' THEN coalesce(prazo_resolucao,public.rc_add_horas_uteis(now(),24)) ELSE prazo_resolucao END,corrigido_por=CASE WHEN p_novo_estado='corrigido' THEN eu ELSE corrigido_por END,correcao_resultado=CASE WHEN p_novo_estado='corrigido' THEN trim(p_texto) ELSE correcao_resultado END,validado_por=CASE WHEN p_novo_estado='validado' THEN eu WHEN p_novo_estado='a_tratar' THEN NULL ELSE validado_por END,validacao_evidencia=CASE WHEN p_novo_estado='validado' THEN trim(p_texto) ELSE validacao_evidencia END,contestado_em=CASE WHEN r.estado IN ('corrigido','nao_procede') AND p_novo_estado='a_tratar' THEN now() ELSE contestado_em END,erro_confirmado=CASE WHEN p_novo_estado='nao_procede' THEN false ELSE erro_confirmado END WHERE id=p_reporte RETURNING * INTO res; PERFORM set_config('app.rc_transicao','0',true); PERFORM set_config('app.central_texto','',true); RETURN res; END $$;
CREATE OR REPLACE FUNCTION public.rc_registar_decisao(p_reporte uuid,p_texto text) RETURNS public.reporte_eventos LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.reporte_eventos; BEGIN IF NOT public.central_gestor() OR NOT public.central_ver(p_reporte) THEN RAISE EXCEPTION 'Só um gestor regista decisões.'; END IF; IF length(trim(coalesce(p_texto,''))) NOT BETWEEN 20 AND 10000 THEN RAISE EXCEPTION 'Fundamenta a decisão.'; END IF; INSERT INTO public.reporte_eventos(reporte_id,autor_id,tipo,texto) VALUES(p_reporte,public.rc_meu_funcionario_id(),'decisao',trim(p_texto)) RETURNING * INTO e; RETURN e; END $$;
CREATE OR REPLACE FUNCTION public.rc_reclassificar(p_reporte uuid,p_nova text,p_motivo text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.reportes; BEGIN IF NOT public.central_gerir(p_reporte) OR p_nova NOT IN ('baixa','media','alta') OR length(trim(coalesce(p_motivo,''))) NOT BETWEEN 10 AND 10000 THEN RAISE EXCEPTION 'Sem permissão ou justificação inválida.'; END IF; SELECT * INTO r FROM public.reportes WHERE id=p_reporte FOR UPDATE; UPDATE public.reportes SET gravidade=p_nova WHERE id=p_reporte; INSERT INTO public.reporte_eventos(reporte_id,autor_id,tipo,texto) VALUES(p_reporte,public.rc_meu_funcionario_id(),'reclassificacao',format('Gravidade %s → %s. %s',r.gravidade,p_nova,p_motivo)); END $$;
CREATE OR REPLACE FUNCTION public.central_diretorio() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN public.rc_meu_funcionario_id() IS NOT NULL THEN coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'nome',nome) ORDER BY nome) FROM public.funcionarios WHERE ativo),'[]'::jsonb) ELSE '[]'::jsonb END; $$;
CREATE OR REPLACE FUNCTION public.central_notificar(p_id uuid,p_texto text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ INSERT INTO public.reporte_notificacoes(reporte_id,destinatario_id,mensagem) SELECT p_id,x,p_texto FROM (SELECT reportado_por x FROM public.reportes WHERE id=p_id UNION SELECT assumido_por FROM public.reportes WHERE id=p_id UNION SELECT funcionario_id FROM public.reporte_envolvidos WHERE reporte_id=p_id AND ativo UNION SELECT f.id FROM public.funcionarios f WHERE f.ativo AND public.has_role(f.user_id,'gestor'::public.app_role) UNION SELECT fs.funcionario_id FROM public.funcionario_setores fs JOIN public.reportes r ON r.setor_destino_id=fs.funcao_id WHERE r.id=p_id AND fs.responsavel) a WHERE x IS NOT NULL AND x<>public.rc_meu_funcionario_id(); $$;
CREATE OR REPLACE FUNCTION public.central_submeter(p_acao text,p_dados jsonb,p_ficheiros uuid[] DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE eu uuid:=public.rc_meu_funcionario_id(); rid uuid; r public.reportes; eid uuid; resp uuid; part uuid; pessoa uuid; f uuid; arr uuid[]; fase text; txt text:=trim(coalesce(p_dados->>'texto','')); novo text; BEGIN IF eu IS NULL OR NOT EXISTS(SELECT 1 FROM public.funcionarios WHERE id=eu AND ativo) THEN RAISE EXCEPTION 'Conta sem colaborador ativo.'; END IF; IF cardinality(p_ficheiros)>10 OR cardinality(p_ficheiros)<>(SELECT count(DISTINCT x) FROM unnest(p_ficheiros) x) THEN RAISE EXCEPTION 'Máximo 10 anexos por submissão.'; END IF;
IF p_acao='criar' THEN IF length(trim(coalesce(p_dados->>'titulo',''))) NOT BETWEEN 5 AND 200 OR length(trim(coalesce(p_dados->>'descricao',''))) NOT BETWEEN 15 AND 10000 THEN RAISE EXCEPTION 'Título ou descrição inválidos.'; END IF; IF coalesce(p_dados->>'gravidade','media') NOT IN ('baixa','media','alta') THEN RAISE EXCEPTION 'Gravidade inválida.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.funcoes WHERE id=(p_dados->>'setor_destino_id')::uuid AND ativo) THEN RAISE EXCEPTION 'Setor destino inválido.'; END IF; IF length(coalesce(p_dados->>'causa_alegada',''))>2000 OR length(coalesce(p_dados->>'referencia_externa',''))>200 OR length(coalesce(p_dados->>'up_care_referencia',''))>200 THEN RAISE EXCEPTION 'Referência ou causa demasiado longa.'; END IF; IF nullif(p_dados->>'referencia_tipo','') IS NOT NULL AND p_dados->>'referencia_tipo' NOT IN ('venda','os','rota','op','outro') THEN RAISE EXCEPTION 'Tipo de referência inválido.'; END IF; INSERT INTO public.reportes(titulo,descricao,setor_origem_id,setor_destino_id,reportado_por,gravidade,ocorrido_em,detetado_em,causa_alegada,referencia_tipo,referencia_externa,up_care_referencia,prazo_resolucao) VALUES(trim(p_dados->>'titulo'),trim(p_dados->>'descricao'),nullif(p_dados->>'setor_origem_id','')::uuid,(p_dados->>'setor_destino_id')::uuid,eu,coalesce(p_dados->>'gravidade','media'),nullif(p_dados->>'ocorrido_em','')::timestamptz,nullif(p_dados->>'detetado_em','')::timestamptz,nullif(p_dados->>'causa_alegada',''),nullif(p_dados->>'referencia_tipo',''),nullif(p_dados->>'referencia_externa',''),nullif(p_dados->>'up_care_referencia',''),nullif(p_dados->>'prazo','')::timestamptz) RETURNING * INTO r; rid:=r.id; fase:='abertura'; txt:='Abertura do reporte. Envolvimento é uma hipótese, sem presunção de culpa.';
ELSE rid:=(p_dados->>'id')::uuid; SELECT * INTO r FROM public.reportes WHERE id=rid FOR UPDATE; IF NOT FOUND OR NOT public.central_ver(rid) THEN RAISE EXCEPTION 'Sem acesso ao reporte.'; END IF; IF length(txt) NOT BETWEEN 15 AND 10000 THEN RAISE EXCEPTION 'Escreve entre 15 e 10000 caracteres.'; END IF; CASE p_acao WHEN 'responder' THEN SELECT id INTO part FROM public.reporte_envolvidos WHERE reporte_id=rid AND funcionario_id=eu AND ativo; IF part IS NULL THEN RAISE EXCEPTION 'Só podes responder à tua participação ativa.'; END IF; INSERT INTO public.reporte_respostas_individuais(envolvido_id,autor_id,resposta,texto) VALUES(part,eu,p_dados->>'resposta',txt) RETURNING id INTO resp; IF p_dados->>'resposta'='contesto' THEN UPDATE public.reportes SET contestado_em=now() WHERE id=rid; END IF; txt:='Resposta individual registada (conteúdo restrito ao autor e gestores).'; fase:='resposta'; WHEN 'comentar' THEN fase:='comentario'; WHEN 'envolvidos' THEN IF NOT public.central_gerir(rid) THEN RAISE EXCEPTION 'Sem permissão para atualizar envolvidos.'; END IF; fase:='atribuicao'; WHEN 'atribuir' THEN IF NOT public.central_gerir(rid) THEN RAISE EXCEPTION 'Sem permissão para atribuir.'; END IF; pessoa:=nullif(p_dados->>'assumido_por','')::uuid; IF NOT EXISTS(SELECT 1 FROM public.funcionarios WHERE id=pessoa AND ativo) THEN RAISE EXCEPTION 'Escolhe um colaborador ativo.'; END IF; UPDATE public.reportes SET assumido_por=pessoa,data_prevista=coalesce(nullif(p_dados->>'data_prevista','')::date,data_prevista),prazo_resolucao=coalesce(nullif(p_dados->>'prazo','')::timestamptz,prazo_resolucao) WHERE id=rid; txt:=txt||' Executor: '||pessoa; fase:='atribuicao'; WHEN 'apurar' THEN IF NOT public.central_gestor() THEN RAISE EXCEPTION 'Só o gestor pode apurar responsabilidade.'; END IF; IF p_dados->>'tipo_causa' NOT IN ('pessoa','processo','sistema','fornecedor','desconhecida') THEN RAISE EXCEPTION 'Tipo de causa inválido.'; END IF; IF length(trim(coalesce(p_dados->>'evidencia',''))) NOT BETWEEN 15 AND 10000 THEN RAISE EXCEPTION 'É necessária evidência fundamentada.'; END IF; SELECT coalesce(array_agg(value::uuid),'{}') INTO arr FROM jsonb_array_elements_text(coalesce(p_dados->'responsaveis','[]')); IF p_dados->>'tipo_causa'<>'pessoa' AND cardinality(arr)>0 THEN RAISE EXCEPTION 'Causas de processo/sistema não atribuem culpa individual.'; END IF; IF EXISTS(SELECT 1 FROM unnest(arr) x WHERE NOT EXISTS(SELECT 1 FROM public.funcionarios WHERE id=x AND ativo)) THEN RAISE EXCEPTION 'Responsável inválido.'; END IF; UPDATE public.reportes SET tipo_causa=p_dados->>'tipo_causa',conclusao=txt,evidencia_apuracao=trim(p_dados->>'evidencia'),erro_confirmado=coalesce((p_dados->>'confirmado')::boolean,false),responsaveis_apurados=arr,apurado_por=eu,apurado_em=now() WHERE id=rid; txt:=txt||' Evidência: '||(p_dados->>'evidencia')||' Causa: '||(p_dados->>'tipo_causa')||' Confirmado: '||coalesce(p_dados->>'confirmado','false')||' Responsáveis apurados: '||coalesce(array_to_string(arr,', '),'nenhum'); fase:='apuracao'; WHEN 'estado' THEN novo:=p_dados->>'estado'; IF novo='corrigido' AND length(trim(coalesce(p_dados->>'resultado',''))) NOT BETWEEN 15 AND 10000 THEN RAISE EXCEPTION 'Descreve o resultado verificado da correção.'; END IF; r:=public.rc_mudar_estado(rid,novo,txt,nullif(p_dados->>'data_prevista','')::date); IF novo='corrigido' THEN UPDATE public.reportes SET correcao_resultado=p_dados->>'resultado' WHERE id=rid; END IF; fase:=CASE WHEN novo='corrigido' THEN 'correcao' WHEN novo IN ('validado','a_tratar') AND r.corrigido_por IS NOT NULL THEN 'validacao' ELSE 'comentario' END; ELSE RAISE EXCEPTION 'Ação inválida.'; END CASE; END IF;
IF p_acao IN ('criar','envolvidos') THEN SELECT coalesce(array_agg(DISTINCT value::uuid),'{}') INTO arr FROM jsonb_array_elements_text(coalesce(p_dados->'envolvidos','[]')); IF cardinality(arr)>50 OR EXISTS(SELECT 1 FROM unnest(arr) x WHERE NOT EXISTS(SELECT 1 FROM public.funcionarios WHERE id=x AND ativo)) THEN RAISE EXCEPTION 'Envolvidos inválidos.'; END IF; UPDATE public.reporte_envolvidos SET ativo=false WHERE reporte_id=rid AND ativo AND NOT(funcionario_id=ANY(arr)); FOREACH pessoa IN ARRAY arr LOOP IF NOT EXISTS(SELECT 1 FROM public.reporte_envolvidos WHERE reporte_id=rid AND funcionario_id=pessoa AND ativo) THEN INSERT INTO public.reporte_envolvidos(reporte_id,funcionario_id,marcado_por) VALUES(rid,pessoa,eu) ON CONFLICT(reporte_id,funcionario_id) DO UPDATE SET ativo=true,marcado_por=eu,marcado_em=now(); INSERT INTO public.reporte_notificacoes(reporte_id,destinatario_id,mensagem) VALUES(rid,pessoa,'Foi indicada a tua participação — sem presunção de culpa. Responde no reporte.'); END IF; END LOOP; txt:=txt||' Participações ativas: '||coalesce(array_to_string(arr,', '),'nenhuma'); END IF;
INSERT INTO public.reporte_eventos(reporte_id,autor_id,tipo,texto) VALUES(rid,eu,CASE WHEN p_acao='apurar' THEN 'decisao' ELSE 'comentario' END,txt) RETURNING id INTO eid; FOREACH f IN ARRAY p_ficheiros LOOP IF NOT EXISTS(SELECT 1 FROM public.reporte_ficheiros a WHERE a.id=f AND a.uploader_id=eu AND a.estado='pendente' AND a.fase=fase AND EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='central-reportes' AND o.name=a.caminho)) THEN RAISE EXCEPTION 'Anexo inválido, reutilizado ou de outro autor.'; END IF; UPDATE public.reporte_ficheiros SET reporte_id=rid,evento_id=eid,resposta_id=resp,estado='ligado',ligado_em=now() WHERE id=f; END LOOP; PERFORM public.central_notificar(rid,CASE p_acao WHEN 'criar' THEN 'Novo reporte' WHEN 'responder' THEN 'Nova resposta / contestação' WHEN 'estado' THEN 'Atualização: '||coalesce(novo,'') ELSE 'Nova atualização do reporte' END); SELECT * INTO r FROM public.reportes WHERE id=rid; RETURN jsonb_build_object('id',rid,'numero',r.numero); END $$;
CREATE OR REPLACE FUNCTION public.central_ler_notificacoes() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.reporte_notificacoes SET lida_em=now() WHERE destinatario_id=public.rc_meu_funcionario_id() AND lida_em IS NULL; $$;
CREATE OR REPLACE FUNCTION public.central_lista() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(d ORDER BY d->>'criado_em' DESC),'[]'::jsonb) FROM (SELECT to_jsonb(r)||jsonb_build_object('origem',o.nome,'destino',s.nome,'criador',f.nome,'executor',a.nome,'envolvidos',coalesce((SELECT jsonb_agg(jsonb_build_object('id',e.funcionario_id,'nome',p.nome)) FROM public.reporte_envolvidos e JOIN public.funcionarios p ON p.id=e.funcionario_id WHERE e.reporte_id=r.id AND e.ativo),'[]'::jsonb)) d FROM public.reportes r LEFT JOIN public.funcoes o ON o.id=r.setor_origem_id JOIN public.funcoes s ON s.id=r.setor_destino_id JOIN public.funcionarios f ON f.id=r.reportado_por LEFT JOIN public.funcionarios a ON a.id=r.assumido_por WHERE public.central_ver(r.id)) q; $$;
CREATE OR REPLACE FUNCTION public.central_metricas() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.central_gestor() THEN RAISE EXCEPTION 'Relatório restrito a gestores.'; END IF; RETURN coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT s.nome setor,r.tipo_causa,date_trunc('month',coalesce(r.ocorrido_em,r.criado_em))::date mes,count(*) FILTER(WHERE r.erro_confirmado AND r.apurado_em IS NOT NULL AND r.estado<>'nao_procede') confirmados,count(*) FILTER(WHERE r.estado IN ('pendente','a_tratar')) pendentes,count(*) FILTER(WHERE r.contestado_em IS NOT NULL) contestados,(SELECT count(*) FROM public.tarefas_dia t WHERE t.funcionario_id IN(SELECT fs.funcionario_id FROM public.funcionario_setores fs WHERE fs.funcao_id=r.setor_destino_id) AND date_trunc('month',t.data::timestamp)=date_trunc('month',coalesce(r.ocorrido_em,r.criado_em))::timestamp) volume_atividades FROM public.reportes r JOIN public.funcoes s ON s.id=r.setor_destino_id GROUP BY s.nome,r.setor_destino_id,r.tipo_causa,date_trunc('month',coalesce(r.ocorrido_em,r.criado_em))) x),'[]'::jsonb); END $$;
CREATE OR REPLACE FUNCTION public.central_storage_ver(p_bucket text,p_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN p_bucket='central-reportes' THEN EXISTS(SELECT 1 FROM public.reporte_ficheiros a WHERE a.caminho=p_path AND a.estado='ligado' AND public.central_ver(a.reporte_id) AND (a.resposta_id IS NULL OR public.central_gestor() OR a.uploader_id=public.rc_meu_funcionario_id())) WHEN p_bucket='qualidade' THEN EXISTS(SELECT 1 FROM public.reportes r WHERE public.central_ver(r.id) AND EXISTS(SELECT 1 FROM unnest(r.anexos) u WHERE position('/qualidade/'||p_path IN u)>0)) OR EXISTS(SELECT 1 FROM public.reporte_eventos e WHERE public.central_ver(e.reporte_id) AND EXISTS(SELECT 1 FROM unnest(e.anexos) u WHERE position('/qualidade/'||p_path IN u)>0)) OR EXISTS(SELECT 1 FROM public.checklist_respostas c JOIN public.checklist_execucoes x ON x.id=c.execucao_id JOIN public.checklist_templates t ON t.id=x.template_id WHERE position('/qualidade/'||p_path IN coalesce(c.foto_url,''))>0 AND (public.central_gestor() OR public.rc_pertence_setor(t.setor_id))) OR EXISTS(SELECT 1 FROM public.checklist_itens i JOIN public.checklist_templates t ON t.id=i.template_id WHERE (public.central_gestor() OR public.rc_pertence_setor(t.setor_id)) AND EXISTS(SELECT 1 FROM unnest(i.instrucao_media) u WHERE position('/qualidade/'||p_path IN u)>0)) ELSE false END; $$;
DROP POLICY IF EXISTS qualidade_read ON storage.objects; CREATE POLICY qualidade_read ON storage.objects FOR SELECT TO authenticated USING((bucket_id='qualidade' AND owner=auth.uid()) OR public.central_storage_ver(bucket_id,name)); CREATE POLICY central_storage_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='central-reportes' AND public.central_storage_ver(bucket_id,name));
REVOKE ALL ON FUNCTION public.central_notificar(uuid,text),public.central_append_only() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.central_gestor(),public.central_ver(uuid),public.central_gerir(uuid),public.central_diretorio(),public.central_submeter(text,jsonb,uuid[]),public.central_ler_notificacoes(),public.central_lista(),public.central_metricas(),public.central_storage_ver(text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.central_gestor(),public.central_ver(uuid),public.central_gerir(uuid),public.central_diretorio(),public.central_submeter(text,jsonb,uuid[]),public.central_ler_notificacoes(),public.central_lista(),public.central_metricas(),public.central_storage_ver(text,text) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.reporte_notificacoes;